def apply(ns):
    """Merge into content.py's namespace (called at the end of content.py)."""
    steps = ns["PEST_STEPS"]
    hub = ns["PEST"]["hub"]
    hub["sectors"], hub["guides"] = list(SECTORS), list(GUIDES)
    for k, d in PEST_NEW.items():
        d["steps"] = steps
        ns["PEST"][k] = d
    for k, v in PEST_EXTRA.items():
        ns["EXTRA"][("pest", k)] = v
    ns["FAC"] = FAC
    for k, v in FAC_EXTRA.items():
        ns["EXTRA"][("fac", k)] = v
